// ConnectionInfo contains diagnostic information about a connection.
type ConnectionInfo struct {
	Address       string
	ActiveConns   int
	TotalConns    int
	InactiveConns int
}

// Dump returns diagnostic information about all connections in the pool.
// This is useful for debugging connection state and diagnosing pool issues.
func (p *connPool) Dump() []ConnectionInfo {
	var result []ConnectionInfo
	p.conns.Range(func(addr, trans interface{}) bool {
		address := addr.(string)
		t := trans.(*transports)

		active := 0
		inactive := 0
		total := int(t.size)

		for i := 0; i < total; i++ {
			if ct := t.cliTransports[i]; ct != nil {
				if ct.(grpc.IsActive).IsActive() {
					active++
				} else {
					inactive++
				}
			}
		}

		result = append(result, ConnectionInfo{
			Address:       address,
			ActiveConns:   active,
			TotalConns:    total,
			InactiveConns: inactive,
		})
		return true
	})
	return result
}

// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

