	if e.Cause != nil {
		return fmt.Sprintf("http2: stream error: stream_id=%d, code=%v, message=%s, cause=%v", 
			e.StreamID, e.Code, e.Message, e.Cause)
	}
	return fmt.Sprintf("http2: stream error: stream_id=%d, code=%v, message=%s", 
		e.StreamID, e.Code, e.Message)
}

