// WithFailureRetry sets the failure retry policy for client, it will take effect for all methods.
func WithFailureRetry(p *retry.FailurePolicy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithFailureRetry(%+v)", p))
		// Store in Unary.RetryMethodPolicies for unary-specific retry configuration
		if o.Unary.RetryMethodPolicies == nil {
			o.Unary.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.Unary.RetryMethodPolicies[retry.Wildcard].MixedPolicy != nil ||
			o.Unary.RetryMethodPolicies[retry.Wildcard].BackupPolicy != nil {
			panic("MixedPolicy or BackupPolicy has been setup, cannot support Failure Retry at same time")
		}
		o.Unary.RetryMethodPolicies[retry.Wildcard] = retry.BuildFailurePolicy(p)

		// Also maintain backward compatibility by setting the global RetryMethodPolicies
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildFailurePolicy(p)
	}}
}

